    extern "C" __global__ void cupy_take(const CArray<float, 1, 1, 1> a, const CArray<int, 1, 1, 1> _raw_indices, const long long ldim_, const long long cdim_, const long long rdim_, const long long index_range_, CArray<float, 1, 1, 1> _raw_out, CIndexer<1, 1> _ind) {
      ;
      #pragma unroll 1
      CUPY_FOR(i, _ind.size()) {
        _ind.set(i);
        const S &indices = _raw_indices[_ind.get()];
T &out = _raw_out[_ind.get()];

using idx_t = decltype(a)::index_t;
idx_t index_range = static_cast<idx_t>(index_range_);
idx_t ldim = static_cast<idx_t>(ldim_);
idx_t cdim = static_cast<idx_t>(cdim_);
idx_t rdim = static_cast<idx_t>(rdim_);

ptrdiff_t out_i = indices % index_range;
if (out_i < 0) out_i += index_range;
if (ldim != 1) out_i += (i / (cdim * rdim)) * index_range;
if (rdim != 1) out_i = out_i * rdim + i % rdim;
out = a[out_i];
;
      }
      ;
    }

