    extern "C" __global__ void cupy_scatter_update(const CArray<int, 1, 1, 1> _raw_v, const CArray<long long, 1, 1, 1> _raw_indices, const long long cdim_, const long long rdim_, const long long adim_, CArray<int, 1, 1, 1> a, CIndexer<1, 1> _ind) {
      ;
      #pragma unroll 1
      CUPY_FOR(i, _ind.size()) {
        _ind.set(i);
        const T &v = _raw_v[_ind.get()];
const S &indices = _raw_indices[_ind.get()];

            using i_idx_t = decltype(i);
            using a_idx_t = decltype(a)::index_t;
            i_idx_t cdim = static_cast<i_idx_t>(cdim_);
            a_idx_t rdim = static_cast<a_idx_t>(rdim_);
            a_idx_t adim = static_cast<a_idx_t>(adim_);

            a_idx_t wrap_indices = indices % adim;
            if (wrap_indices < 0) wrap_indices += adim;
            a_idx_t li = i / (rdim * cdim);
            a_idx_t ri = i % rdim;
            T &out0 = a[(li * adim + wrap_indices) * rdim + ri];
            const T &in1 = v;
            out0 = in1;
        ;
      }
      ;
    }

