            value = mpas_add(value, mpas_mul(mpas_div(mpas_mul(
                cell_sign(cell, edge, cells_on_edge), dv_edge[edge]),
                area_cell[cell]), delsq_u[lidx(k, edge, nedges)]));
        }
        delsq_divergence[lidx(k, cell, ncells)] = value;
