            DZSNSO(j) = f_min(f_max(DZSNSO(j), FDIV(FADD(SNICE(j), SNLIQ(j)), SN_K_500)),
                              FDIV(FADD(SNICE(j), SNLIQ(j)), SN_K_50));
        }

        burden = FADD(burden, wx);
    }
}

