                dtdz = FDIV(FSUB(TSNO(1), TSNO(2)), FDIV(FADD(DZ(1), DZ(2)), SN_K_TWO));
                DZ(2) = FDIV(DZ(2), SN_K_TWO);
                SWICE(2) = FDIV(SWICE(2), SN_K_TWO);
                SWLIQ(2) = FDIV(SWLIQ(2), SN_K_TWO);
                DZ(3) = DZ(2);
                SWICE(3) = SWICE(2);
                SWLIQ(3) = SWLIQ(2);
                TSNO(3) = FSUB(TSNO(2), FDIV(FMUL(dtdz, DZ(2)), SN_K_TWO));
