    if (msno > 2) {
        if (DZ(2) > SN_K_P2) {
            drr = FSUB(DZ(2), SN_K_P2);
            propor = FDIV(drr, DZ(2));
            zwice = FMUL(propor, SWICE(2));
            zwliq = FMUL(propor, SWLIQ(2));
