    for (int k = 0; k < nsoil; ++k) {
        zsoil[k] = xin[SI_IN_ZSOIL + k];
    }
    for (int k = 0; k < nsnow + nsoil; ++k) {
        zsnso[k] = xin[SI_IN_ZSNSO + k];
    }
    for (int k = 0; k < nsnow; ++k) {
        tsno[k] = xin[SI_IN_TSNO + k];
        snice[k] = xin[SI_IN_SNICE + k];
        snliq[k] = xin[SI_IN_SNLIQ + k];
