// just as happily as the FP32 form, and glibc's polynomials are evaluated
// without contraction on x86-64.
#define DAD(a, b) __dadd_rn((a), (b))
#define DSU(a, b) __dsub_rn((a), (b))
#define DMU(a, b) __dmul_rn((a), (b))

