    real expon = AD(bexp, 2.0f);                                   // :9178
    real wdf = MU(dwsat, r_pow(factr, expon));                     // :9179
    wdf = MU(wdf, SU(1.0f, fcr));                                  // :9180
    expon = AD(MU(2.0f, bexp), 3.0f);                              // :9184
    real wcnd = MU(dksat, r_pow(factr, expon));                    // :9185
