#define RLW_DV(a, b) __fdiv_rn((a), (b))
#define RLW_DAD(a, b) __dadd_rn((a), (b))
#define RLW_DSU(a, b) __dsub_rn((a), (b))
#define RLW_DMU(a, b) __dmul_rn((a), (b))

