        int indm = IS(SI_INDMINOR);

        for (int ig = 1; ig <= ng9; ++ig) {
            float absn2o = RLW_AD(A2(kb_mn2o, 19, indm, ig),
                RLW_MU(FS(SL_MINORFRAC),
