                                       chi_mls[1 + 7 * 0]);
        float refrat_m_a = RLW_DV(chi_mls[3 + 7 * 0], chi_mls[1 + 7 * 0]);

        float coln2o = FS(SL_COLN2O);
        float colco2 = FS(SL_COLCO2);

