    extern "C" __global__ void cupy_nonzero_kernel_incomplete_scan(const CArray<bool, 2, 1, 1> a, const CArray<int, 1, 1, 1> b, CArray<long long, 2, 1, 1> dst, CIndexer<1, 1> _ind) {

        __shared__ S smem[32];
        const int n_warp = 512 / 32;
        const int warp_id = threadIdx.x / 32;
        const int lane_id = threadIdx.x % 32;
    ;
      #pragma unroll 1
      CUPY_FOR(i, _ind.size()) {
        _ind.set(i);

        S x = 0;
        if (i < a.size()) x = a[i];
        for (int j = 1; j < 32; j *= 2) {
            S tmp = __shfl_up_sync(0xffffffff, x, j, 32);
            if (lane_id - j >= 0) x += tmp;
        }
        if (lane_id == 32 - 1) smem[warp_id] = x;
        __syncthreads();
        if (warp_id == 0) {
            S y = 0;
            if (lane_id < n_warp) y = smem[lane_id];
            for (int j = 1; j < n_warp; j *= 2) {
                S tmp = __shfl_up_sync(0xffffffff, y, j, 32);
                if (lane_id - j >= 0) y += tmp;
            }
            int block_id = i / 512;
            S base = 0;
            if (block_id > 0) base = b[block_id - 1];
            if (lane_id == 32 - 1) y = 0;
            smem[(lane_id + 1) % 32] = y + base;
        }
        __syncthreads();
        x += smem[warp_id];
        S x0 = __shfl_up_sync(0xffffffff, x, 1, 32);
        if (lane_id == 0) {
            x0 = smem[warp_id];
        }
        if (x0 < x && i < a.size()) {
            O j = i;
            for (int d = a.ndim - 1; d >= 0; d--) {
                ptrdiff_t ind[] = {x0, d};
                O j_next = j / a.shape()[d];
                dst[ind] = j - j_next * a.shape()[d];
                j = j_next;
            }
        }
    ;
      }
      ;
    }

__device__ float A(float a,float b){return __fadd_rn(a,b);}
__device__ float S(float a,float b){return __fsub_rn(a,b);}
