    real solad1 = MU(MU(swdown, 0.7f), 0.5f);                      // :1158
    real solai1 = MU(MU(swdown, 0.3f), 0.5f);                      // :1160

    real prcp = AD(AD(prcpconv, prcpnonc), prcpshcv);              // :1163
    real qprecc = MU(0.10f, prcp);                                 // :1169
    real qprecl = MU(0.90f, prcp);                                 // :1170

