#define NG_SB     5.67e-08f
#define NG_VKC    0.40f
#define NG_HSUB   2.8440e06f
#define NG_HFUS   0.3336e06f
#define NG_Z0SNO  0.002f
#define NG_SSI    0.03f
#define NG_SWEMX  1.00f
