        float tmp22 = r_log(DV(AD(1.0f, MU(tmp12, tmp12)), 2.0f));
        float tmp32 = r_log(DV(AD(1.0f, tmp12), 2.0f));
        fm2new = AD(SU(AD(MU(2.0f, tmp32), tmp22),
                       MU(2.0f, ng_atanf(tmp12))), 1.5707963f);
        fh2new = MU(2.0f, tmp22);
