        fhnew = fmnew;
        fm2new = MU(-5.0f, moz2);
        fh2new = fm2new;
    }

    if (it == 1) {
        s->fm = fmnew;
        s->fh = fhnew;
        s->fm2 = fm2new;
        s->fh2 = fh2new;
    } else {
        s->fm = MU(0.5f, AD(s->fm, fmnew));
        s->fh = MU(0.5f, AD(s->fh, fhnew));
        s->fm2 = MU(0.5f, AD(s->fm2, fm2new));
        s->fh2 = MU(0.5f, AD(s->fh2, fh2new));
